I'm having a very hard time seeing this as an improvement over apache/nginx/lighttpd text-<em>file</em> configuration. Web server configs also have a tendency to be heirarchical, which sounds extra-painful in SQL.<p>Let's take a real-world nginx conf for example (comments and blank lines elided to save space). I can't imagine how trying to shoehorn something like this into sql is a win. Even Java-style XML situps seem preferable:<p><pre><code>  http {
  include /usr/local/nginx/conf/mime.types;
  default_type  application/octet-stream;
  log_format main '$remote_addr - $remote_user [$time_local] '
                  '"$request" $status $body_bytes_sent "$http_referer" '
                  '"$http_user_agent" "$http_x_forwarded_for"';
  access_log  /var/log/nginx_access.log  main;
  error_log  /var/log/nginx_error.log debug;
  sendfile on;
  tcp_nopush        on;
  tcp_nodelay       off;
  gzip            on;
  gzip_http_version 1.0;
  gzip_comp_level 2;
  gzip_proxied any;
  gzip_types      text/plain text/html text/css application/x-javascript text/xml application/xml application/xml+rss text/javascript;
  upstream mongrel {
    server 127.0.0.1:5000;
    # server 127.0.0.1:5001;
    # server 127.0.0.1:5002;
  }
  server {
    listen 80;
    client_max_body_size 50M;
    root /var/www/apps/mysite.com/current/public;
    access_log  /var/www/apps/mysite.com/shared/log/nginx.vhost.access.log  main;

    if (-f $document_root/system/maintenance.html) {
      rewrite  ^(.*)$  /system/maintenance.html last;
      break;
    }
    location / {
      <em>proxy</em>_set_header  X-Real-IP  $remote_addr;
      <em>proxy</em>_set_header  X-Forwarded-For $proxy_add_x_forwarded_for;
      <em>proxy</em>_set_header Host $http_host;
      <em>proxy</em>_redirect false;
      <em>proxy</em>_max_<em>temp</em>_<em>file</em>_size 0;

      if (-f $request_filename) { 
        break; 
      }
      if (-f $request_filename/index.html) {
        rewrite (.*) $1/index.html break;
      }
      if (-f $request_filename.html) {
        rewrite (.*) $1.html break;
      }
      if (!-f $request_filename) {
        <em>proxy</em>_pass http://mongrel;
        break;
      }
    }
    error_page   500 502 503 504  /500.html;
    location = /500.html {
      root   /var/www/apps/mysite.com/current/public;
    }
  }</code></pre>

